"""Regenerate CUDA constants from installed SciPy (recorded version/source hash)."""

import hashlib
from pathlib import Path

import scipy
from scipy.integrate._ivp import dop853_coefficients as d

root = Path(__file__).resolve().parents[2]
source = Path(d.__file__)
license_file = next(Path(scipy.__file__).parent.parent.glob("scipy-*.dist-info/LICENSE.txt"))
license_text = license_file.read_text().split("\n----")[0].strip()
arrays = {"C": d.C[:12], "A": d.A[:12, :12], "B": d.B, "E3": d.E3, "E5": d.E5}
lines = [
    "// Generated by scripts/gpu/generate_dop853_coefficients.py.",
    f"// SciPy {scipy.__version__}; dop853_coefficients.py SHA256 "
    + hashlib.sha256(source.read_bytes()).hexdigest(),
    "// https://github.com/scipy/scipy/blob/main/scipy/integrate/_ivp/dop853_coefficients.py",
    "/*\n" + license_text + "\n*/",
    "#pragma once",
    "namespace dop853 {",
]
for name, values in arrays.items():
    dimensions = "".join(f"[{n}]" for n in values.shape)
    if values.ndim == 1:
        body = ", ".join(format(float(x), ".17g") for x in values)
    else:
        body = ",\n".join(
            "{" + ", ".join(format(float(x), ".17g") for x in row) + "}" for row in values
        )
    lines.append(f"__device__ __constant__ double {name}{dimensions} = {{{body}}};")
lines.append("} // namespace dop853\n")
(root / "cpp/cuda/internal/dop853_coefficients.cuh").write_text("\n".join(lines))
license_output = root / "third_party/licenses/scipy-dop853.txt"
license_output.parent.mkdir(parents=True, exist_ok=True)
license_output.write_text(license_text + "\n")
